library offline_sync_generator.builder;

import 'package:build/build.dart';
import 'package:source_gen/source_gen.dart';
import 'src/sync_entity_generator.dart';

/// Builder factory for `build_runner`.
Builder syncEntityBuilder(BuilderOptions options) {
  return LibraryBuilder(
    SyncEntityGenerator(),
    generatedExtension: '.sync.g.dart',
    header: '''// GENERATED CODE - DO NOT MODIFY BY HAND
// Generated by offline_sync_generator

import 'package:test/test.dart';
import 'package:offline_sync/offline_sync.dart';
''',
  );
}
